namespace ghidra.app.plugin.core.datamgr;

using static org.junit.Assert;






using org.junit;

using generic.jar;
using generic.test;
using ghidra.framework;
using ghidra.program.database.dtarchive;
using ghidra.program.model.dtarchive;
using ghidra.program.model.dtarchive;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

public class RustDataTypeArchiveIDTest : AbstractGenericTest {

	//@formatter:off
	private static readonly Map<string, string> archiveIdMap = Map.ofEntries(
			Map.entry("typeinfo/rust-common.gdt", "3557867258392862055"));
	//@formatter:on

	private Map<ResourceFile, string> getCurrentGdts() {
		return Application.findFilesByExtensionInMyModule(".gdt")
				.stream()
				.filter(f => f.getAbsolutePath().replace('\\', '/').contains("/data/typeinfo/"))
				.collect(Collectors.toMap(Function.identity(), f => getGdtUniversalId(f)));
	}

	private string getGdtUniversalId(ResourceFile gdtFile) {
		FileDataTypeArchive archive = null;
		try {
			archive = DataTypeArchiveFactory.openReadOnly(gdtFile, this, TaskMonitor.DUMMY);
			assertEquals(archive.getWarningMessage(true), ArchiveWarning.NONE,
				archive.getWarning());
			return archive.getUniversalID().toString();
		}
		catch (Exception e) when (e is IOException or CancelledException or VersionException) {
			return "failed to read " + gdtFile.getName();
		}
		finally {
			archive.release(this);
		}
	}

	private string getGdtRelativePath(ResourceFile gdtFile) {
		string path = gdtFile.getAbsolutePath().replace('\\', '/');
		int ix = path.indexOf("/typeinfo/");
		path = path.substring(ix + 1);
		return path;
	}

	/* @Test */
	public void testArchiveIDMatch() {

		Map<ResourceFile, string> currentGdts = getCurrentGdts();
		Set<string> notFound = new(archiveIdMap.keySet());
		foreach (ResourceFile gdtFile in currentGdts.keySet()) {
			string currentID = currentGdts.get(gdtFile);

			string gdtRelativePath = getGdtRelativePath(gdtFile);
			string oldID = archiveIdMap.get(gdtRelativePath);
			if (oldID == null) {
				fail("New archive added, test must be updated: %s, ID: %s"
						.formatted(gdtRelativePath, currentID));
			}

			notFound.remove(gdtRelativePath);

			assertEquals("Archive UniversalID mismatch: " + gdtRelativePath, oldID, currentID);
		}

		if (!notFound.isEmpty()) {
			Console.WriteLine("The following standard archives were not found:");
			foreach (string p in notFound) {
				Console.WriteLine("missing archive: " + p);
			}
			fail("One or more standard archives are missing");
		}

	}
}
